/**
 * src/orchestrator/config.ts — merges the user-editable budget
 * (`config/bot.json`, committed) with the discovered dungeon economics
 * (`config/discovered.json`, generated by `scripts/probe.ts`, gitignored).
 *
 * Fails closed if either is missing rather than falling back to a guessed
 * number — CLAUDE.md §1, "discover, don't assume."
 */

import { existsSync, readFileSync } from "node:fs";
import { z } from "zod";

const BotJsonSchema = z.object({
  forbiddenWoods: z.object({
    dailyEnergyBudget: z.number().positive(),
    maxRunsPerSession: z.number().int().positive(),
    // Session 17: explicit user opt-in required before the live loop uses
    // ANY potion — absent, no potions are used, full stop. Prevents the
    // loop from auto-consuming a limited/valuable consumable it merely
    // finds in inventory without the user having actually authorized it,
    // per the user's direct instruction this session.
    potions: z
      .object({
        allowedItemId: z.number().int().positive(),
        maxPerRun: z.number().int().positive(),
      })
      .optional(),
    // [session 55] The deliberate suboptimal boon pick that buys a pickup
    // pair for an unmodelled boon (`src/strategy/boonCapture.ts`). Absent
    // means OFF, and `enabled: false` also means off — but note that this
    // block being present and enabled is only HALF the gate: `liveRun.ts`
    // additionally requires `--boon-capture` on the command line. Two
    // conditions, deliberately, because the potion block next door taught
    // this repo what a one-condition gate costs (session 24).
    boonCapture: z
      .object({
        enabled: z.boolean(),
        targets: z.array(z.string().min(1)).nonempty().optional(),
        rooms: z.array(z.number().int().positive()).nonempty().optional(),
      })
      .optional(),
    // [session 56] The user's boon directive (`src/strategy/boonPriority.ts`).
    // NOT a gate — unlike `boonCapture` above, the directive is ON in live
    // play whether or not this block exists, because it is the user's
    // instruction about how to play rather than a measurement that costs run
    // quality. This block only lets the one number in it be read without a
    // code change. Absent means the shipped default (rooms 1..8).
    //
    // [session 58] `orbRule` MUST be listed here even though it has a code
    // default: zod strips unknown keys silently, so an unlisted knob would
    // read as absent and setting it to "tie-break" to revert session 58's
    // change would do nothing at all — a config that lies rather than fails.
    boonPriority: z
      .object({
        earlyGameMaxRoom: z.number().int().positive(),
        orbRule: z.enum(["tie-break", "wide"]).optional(),
      })
      .optional(),
  }),
  dendren: z
    .object({
      dailyEnergyBudget: z.number().positive(),
      maxCastsPerSession: z.number().int().positive(),
      // [session 61 §4c] Oils, mirroring `forbiddenWoods.potions`: the user
      // sets the budget, the bot spends within it autonomously and stops. The
      // THIRD field has no potions analogue and is the important one —
      // `policyApproved` is CLAUDE.md rule 4's gate, false until the user has
      // approved a derived timing policy. Absent block = no oil ever spent.
      oils: z
        .object({
          allowedItemIds: z.array(z.number().int().positive()).min(1),
          maxPerCast: z.number().int().positive().max(3),
          // [session 69 §4] Per-item ceiling, keyed by item id as a string.
          // Absent id = no per-item cap ("Focus: unconstrained"), which is
          // deliberately expressed by silence rather than by a number.
          perItemMaxPerCast: z.record(z.string(), z.number().int().nonnegative().max(3)).optional(),
          policyApproved: z.boolean(),
        })
        .optional(),
    })
    .optional(),
  guards: z.object({
    maxConsecutiveActionFailures: z.number().int().positive(),
  }),
});

const DiscoveredJsonSchema = z.object({
  forbiddenWoods: z.object({
    id: z.number(),
    energyCost: z.number().positive(),
    maxRoom: z.number().int().positive(),
    maxRunsPerDay: z.number().int().positive(),
  }),
  dendren: z
    .object({
      nodeId: z.string(),
      pondId: z.number(),
      gridSize: z.number(),
      tiers: z.record(
        z.string(),
        z.object({ name: z.string(), energyCost: z.number().positive() }).passthrough(),
      ),
      maxCastsPerDay: z.number().int().positive(),
    })
    .optional(),
});

export interface BotConfig {
  dungeonId: number;
  energyCostPerRun: number;
  maxRoom: number;
  maxRunsPerDayGame: number;
  dailyEnergyBudget: number;
  maxRunsPerSession: number;
  maxConsecutiveActionFailures: number;
  /** User-authorized potion, session 17 — absent means "no potions," not "figure it out from inventory." */
  potions?: { allowedItemId: number; maxPerRun: number };
  /**
   * [session 55] Absent means the boon-capture override is off. Present and
   * `enabled` is still not sufficient on its own — see the schema comment
   * and `liveRun.ts`'s `main()`. `targets`/`rooms` fall back to
   * `boonCapture.ts`'s measured defaults when omitted.
   */
  boonCapture?: { enabled: boolean; targets?: string[]; rooms?: number[] };
  /**
   * [session 56] The lifesteal demotion window. Absent means
   * `boonPriority.ts`'s shipped `EARLY_GAME_MAX_ROOM` (8, user-confirmed).
   * Not a gate — see the schema comment.
   */
  boonPriority?: { earlyGameMaxRoom: number; orbRule?: "tie-break" | "wide" };
  dendren?: {
    nodeId: string;
    tierId: number;
    energyCostPerCast: number;
    maxCastsPerDayGame: number;
    dailyEnergyBudget: number;
    maxCastsPerSession: number;
    /** [session 61 §4c] User-authorized oils — absent means "no oils", not "work it out from inventory." */
    oils?: {
      allowedItemIds: number[];
      maxPerCast: number;
      /** [session 69 §4] Per-item per-cast ceiling, keyed by item id as a string. Absent id = uncapped. */
      perItemMaxPerCast?: Record<string, number>;
      policyApproved: boolean;
    };
  };
}

export class MissingConfigError extends Error {
  constructor(path: string, hint: string) {
    super(`Missing config file: ${path}\n${hint}`);
    this.name = "MissingConfigError";
  }
}

export function loadBotConfig(
  botJsonPath = "config/bot.json",
  discoveredJsonPath = "config/discovered.json",
): BotConfig {
  if (!existsSync(botJsonPath)) {
    throw new MissingConfigError(botJsonPath, "This file is committed — it should exist. Check you're in the repo root.");
  }
  if (!existsSync(discoveredJsonPath)) {
    throw new MissingConfigError(
      discoveredJsonPath,
      "Generated by `npm run probe` — it's gitignored and must be produced locally before any live run.",
    );
  }

  const bot = BotJsonSchema.parse(JSON.parse(readFileSync(botJsonPath, "utf8")));
  const discovered = DiscoveredJsonSchema.parse(JSON.parse(readFileSync(discoveredJsonPath, "utf8")));

  // Dendren is optional on both sides — a repo that hasn't run Task 7/9 yet
  // (or a discovered.json predating the dendren block) still gets a valid
  // dungeon-only BotConfig, per this file's own fail-closed-per-feature
  // convention rather than a monolithic all-or-nothing parse.
  let dendren: BotConfig["dendren"];
  if (discovered.dendren && bot.dendren) {
    const tier1 = discovered.dendren.tiers["1"];
    if (!tier1) {
      throw new MissingConfigError(discoveredJsonPath, "dendren.tiers['1'] (the free tier) is missing — re-run Task 7's discovery.");
    }
    dendren = {
      nodeId: discovered.dendren.nodeId,
      tierId: 1,
      energyCostPerCast: tier1.energyCost,
      maxCastsPerDayGame: discovered.dendren.maxCastsPerDay,
      dailyEnergyBudget: bot.dendren.dailyEnergyBudget,
      maxCastsPerSession: bot.dendren.maxCastsPerSession,
      oils: bot.dendren.oils,
    };
  }

  return {
    dungeonId: discovered.forbiddenWoods.id,
    energyCostPerRun: discovered.forbiddenWoods.energyCost,
    maxRoom: discovered.forbiddenWoods.maxRoom,
    maxRunsPerDayGame: discovered.forbiddenWoods.maxRunsPerDay,
    dailyEnergyBudget: bot.forbiddenWoods.dailyEnergyBudget,
    maxRunsPerSession: bot.forbiddenWoods.maxRunsPerSession,
    maxConsecutiveActionFailures: bot.guards.maxConsecutiveActionFailures,
    potions: bot.forbiddenWoods.potions,
    boonCapture: bot.forbiddenWoods.boonCapture,
    boonPriority: bot.forbiddenWoods.boonPriority,
    dendren,
  };
}
